diff --git a/lib/lexer/shorthand.js b/lib/lexer/shorthand.js
new file mode 100644
index 0000000..c0c20b7
--- /dev/null
+++ b/lib/lexer/shorthand.js
@@ -0,0 +1,441 @@
+const CSS_WIDE = ['inherit', 'initial', 'unset', 'revert', 'revert-layer'];
+
+const INITIAL = {
+    'margin-top': '0', 'margin-right': '0', 'margin-bottom': '0', 'margin-left': '0',
+    'padding-top': '0', 'padding-right': '0', 'padding-bottom': '0', 'padding-left': '0',
+    'top': 'auto', 'right': 'auto', 'bottom': 'auto', 'left': 'auto',
+    'border-top-left-radius': '0', 'border-top-right-radius': '0',
+    'border-bottom-right-radius': '0', 'border-bottom-left-radius': '0',
+    'border-width': 'medium', 'border-style': 'none', 'border-color': 'currentcolor',
+    'border-top-width': 'medium', 'border-top-style': 'none', 'border-top-color': 'currentcolor',
+    'border-right-width': 'medium', 'border-right-style': 'none', 'border-right-color': 'currentcolor',
+    'border-bottom-width': 'medium', 'border-bottom-style': 'none', 'border-bottom-color': 'currentcolor',
+    'border-left-width': 'medium', 'border-left-style': 'none', 'border-left-color': 'currentcolor',
+    'outline-width': 'medium', 'outline-style': 'none', 'outline-color': 'auto',
+    'list-style-type': 'disc', 'list-style-position': 'outside', 'list-style-image': 'none',
+    'text-decoration-line': 'none', 'text-decoration-style': 'solid',
+    'text-decoration-color': 'currentcolor', 'text-decoration-thickness': 'auto',
+    'flex-direction': 'row', 'flex-wrap': 'nowrap',
+    'flex-grow': '0', 'flex-shrink': '1', 'flex-basis': 'auto',
+    'overflow-x': 'visible', 'overflow-y': 'visible', 'row-gap': 'normal', 'column-gap': 'normal',
+    'background-image': 'none', 'background-position': '0% 0%', 'background-size': 'auto',
+    'background-repeat': 'repeat', 'background-origin': 'padding-box',
+    'background-clip': 'border-box', 'background-attachment': 'scroll', 'background-color': 'transparent',
+    'font-style': 'normal', 'font-variant': 'normal', 'font-weight': 'normal',
+    'font-stretch': 'normal', 'font-size': 'medium', 'line-height': 'normal', 'font-family': 'initial'
+};
+
+const LONGHANDS = {
+    margin: ['margin-top', 'margin-right', 'margin-bottom', 'margin-left'],
+    padding: ['padding-top', 'padding-right', 'padding-bottom', 'padding-left'],
+    inset: ['top', 'right', 'bottom', 'left'],
+    'border-radius': ['border-top-left-radius', 'border-top-right-radius', 'border-bottom-right-radius', 'border-bottom-left-radius'],
+    overflow: ['overflow-x', 'overflow-y'],
+    gap: ['row-gap', 'column-gap'],
+    border: ['border-width', 'border-style', 'border-color'],
+    'border-top': ['border-top-width', 'border-top-style', 'border-top-color'],
+    'border-right': ['border-right-width', 'border-right-style', 'border-right-color'],
+    'border-bottom': ['border-bottom-width', 'border-bottom-style', 'border-bottom-color'],
+    'border-left': ['border-left-width', 'border-left-style', 'border-left-color'],
+    outline: ['outline-width', 'outline-style', 'outline-color'],
+    'list-style': ['list-style-type', 'list-style-position', 'list-style-image'],
+    'text-decoration': ['text-decoration-line', 'text-decoration-style', 'text-decoration-color', 'text-decoration-thickness'],
+    'flex-flow': ['flex-direction', 'flex-wrap'],
+    flex: ['flex-grow', 'flex-shrink', 'flex-basis'],
+    background: ['background-image', 'background-position', 'background-size', 'background-repeat', 'background-origin', 'background-clip', 'background-attachment', 'background-color'],
+    font: ['font-style', 'font-variant', 'font-weight', 'font-stretch', 'font-size', 'line-height', 'font-family']
+};
+
+const BOX = ['margin', 'padding', 'inset', 'border-radius'];
+const TWO = ['overflow', 'gap'];
+
+function has(list, item) {
+    return list.indexOf(item) !== -1;
+}
+
+function splitValue(value) {
+    const layers = [];
+    let layer = [];
+    let buf = '';
+    let depth = 0;
+    let quote = '';
+    const flush = () => {
+        if (buf !== '') {
+            layer.push(buf); buf = '';
+        }
+    };
+    const next = () => {
+        flush(); layers.push(layer); layer = [];
+    };
+    for (let i = 0; i < value.length; i++) {
+        const ch = value[i];
+        if (quote) {
+            buf += ch; if (ch === '\\') {
+                i++; if (i < value.length) {
+                    buf += value[i];
+                }
+            } else if (ch === quote) {
+                quote = '';
+            } continue;
+        }
+        if (ch === '\\') {
+            buf += ch; i++; if (i < value.length) {
+                buf += value[i];
+            } continue;
+        }
+        if (ch === '"' || ch === "'") {
+            quote = ch; buf += ch; continue;
+        }
+        if (ch === '(' || ch === '[' || ch === '{') {
+            depth++; buf += ch; continue;
+        }
+        if (ch === ')' || ch === ']' || ch === '}') {
+            depth--; buf += ch; continue;
+        }
+        if (depth === 0 && (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r')) {
+            flush(); continue;
+        }
+        if (depth === 0 && ch === ',') {
+            next(); continue;
+        }
+        if (depth === 0 && ch === '/') {
+            flush(); layer.push('/'); continue;
+        }
+        buf += ch;
+    }
+    flush();
+    layers.push(layer);
+    return layers.filter((item, idx) => item.length || idx === 0);
+}
+
+function distribute(tokens) {
+    if (!tokens || tokens.length < 1 || tokens.length > 4) {
+        return null;
+    }
+    for (const token of tokens) {
+        if (token === '/') {
+            return null;
+        }
+    }
+    const n = tokens.length;
+    if (n === 1) {
+        return [tokens[0], tokens[0], tokens[0], tokens[0]];
+    }
+    if (n === 2) {
+        return [tokens[0], tokens[1], tokens[0], tokens[1]];
+    }
+    if (n === 3) {
+        return [tokens[0], tokens[1], tokens[2], tokens[1]];
+    }
+    return tokens.slice(0, 4);
+}
+
+function expandBox(longhands, layers, result) {
+    const tokens = layers[0];
+    const slash = tokens.indexOf('/');
+    if (longhands[0] === 'border-top-left-radius' && slash !== -1) {
+        const h = distribute(tokens.slice(0, slash));
+        const v = distribute(tokens.slice(slash + 1));
+        if (!h || !v) {
+            return null;
+        }
+        for (let i = 0; i < 4; i++) {
+            result[longhands[i]] = h[i] === v[i] ? h[i] : h[i] + ' ' + v[i];
+        }
+        return result;
+    }
+    const values = distribute(tokens);
+    if (!values) {
+        return null;
+    }
+    for (let i = 0; i < 4; i++) {
+        result[longhands[i]] = values[i];
+    }
+    return result;
+}
+
+function expandTwo(longhands, layers, result) {
+    const tokens = layers[0];
+    if (tokens.length < 1 || tokens.length > 2) {
+        return null;
+    }
+    result[longhands[0]] = tokens[0];
+    result[longhands[1]] = tokens.length === 2 ? tokens[1] : tokens[0];
+    return result;
+}
+
+function assignTokens(lexer, names, tokens, result) {
+    for (const name of names) {
+        result[name] = null;
+    }
+    for (const token of tokens) {
+        if (token === '/') {
+            continue;
+        }
+        let found = null;
+        for (const name of names) {
+            if (result[name] !== null) {
+                continue;
+            }
+            const match = lexer.matchProperty(name, token);
+            if (match && match.matched) {
+                found = name; break;
+            }
+        }
+        if (!found) {
+            return null;
+        }
+        result[found] = token;
+    }
+    for (const name of names) {
+        if (result[name] === null) {
+            result[name] = INITIAL[name] || 'initial';
+        }
+    }
+    return result;
+}
+
+function expandComponents(lexer, longhands, layers, result) {
+    return assignTokens(lexer, longhands, layers[0], result);
+}
+
+function expandBackground(lexer, longhands, layers, result) {
+    const perLayer = [];
+    for (const tokens of layers) {
+        if (!tokens.length) {
+            return null;
+        }
+        const map = {};
+        for (const token of tokens) {
+            if (token === '/') {
+                map['background-size/'] = true; continue;
+            }
+            if (map['background-size/'] === true) {
+                map['background-size/'] = false; map['background-size'] = token; continue;
+            }
+            if (map['background-image'] === undefined && lexer.matchProperty('background-image', token).matched) {
+                map['background-image'] = token; continue;
+            }
+            if (map['background-repeat'] === undefined && lexer.matchProperty('background-repeat', token).matched) {
+                map['background-repeat'] = token; continue;
+            }
+            if (map['background-attachment'] === undefined && lexer.matchProperty('background-attachment', token).matched) {
+                map['background-attachment'] = token; continue;
+            }
+            if (map['background-color'] === undefined && lexer.matchProperty('background-color', token).matched) {
+                map['background-color'] = token; continue;
+            }
+            if (lexer.matchProperty('background-position', token).matched) {
+                map['background-position'] = map['background-position'] ? map['background-position'] + ' ' + token : token; continue;
+            }
+            if (lexer.matchProperty('background-origin', token).matched) {
+                if (map['background-origin'] === undefined) {
+                    map['background-origin'] = token;
+                } else if (map['background-clip'] === undefined) {
+                    map['background-clip'] = token;
+                } else {
+                    return null;
+                } continue;
+            }
+            if (map['background-size/'] === true && lexer.matchProperty('background-size', token).matched) {
+                map['background-size/'] = false; map['background-size'] = token; continue;
+            }
+            return null;
+        }
+        if (map['background-size/'] === true) {
+            return null;
+        }
+        perLayer.push(map);
+    }
+    for (const name of longhands) {
+        if (name === 'background-color') {
+            continue;
+        }
+        result[name] = perLayer.map(map => map[name] !== undefined ? map[name] : INITIAL[name]).join(', ');
+    }
+    const last = perLayer[perLayer.length - 1];
+    result['background-color'] = last['background-color'] !== undefined ? last['background-color'] : INITIAL['background-color'];
+    return result;
+}
+
+function assignFontBefore(lexer, longhands, tokens, result) {
+    const names = longhands.slice(0, 4);
+    return assignTokens(lexer, names, tokens, result);
+}
+
+function expandFont(lexer, longhands, layers, result) {
+    const tokens = layers[0];
+    const slash = tokens.indexOf('/');
+    if (slash !== -1) {
+        const size = tokens[slash - 1];
+        const line = tokens[slash + 1];
+        if (size === undefined || line === undefined) {
+            return null;
+        }
+        result['font-size'] = size;
+        result['line-height'] = line;
+        const rest = tokens.slice(slash + 2);
+        if (!rest.length) {
+            return null;
+        }
+        result['font-family'] = rest.join(' ');
+        return assignFontBefore(lexer, longhands, tokens.slice(0, slash - 1), result);
+    }
+    let sizeIndex = -1;
+    for (let i = 0; i < tokens.length; i++) {
+        if (lexer.matchProperty('font-size', tokens[i]).matched) {
+            sizeIndex = i; break;
+        }
+    }
+    if (sizeIndex === -1 || sizeIndex + 1 >= tokens.length) {
+        return null;
+    }
+    result['font-size'] = tokens[sizeIndex];
+    result['line-height'] = INITIAL['line-height'];
+    result['font-family'] = tokens.slice(sizeIndex + 1).join(' ');
+    return assignFontBefore(lexer, longhands, tokens.slice(0, sizeIndex), result);
+}
+
+export function expandShorthand(lexer, propertyName, value) {
+    const name = String(propertyName).toLowerCase();
+    const longhands = LONGHANDS[name];
+    if (!longhands) {
+        return null;
+    }
+    if (typeof value !== 'string') {
+        value = String(value);
+    }
+    const trimmed = value.trim();
+    if (!trimmed) {
+        return null;
+    }
+    const lower = trimmed.toLowerCase();
+    const result = {};
+    if (has(CSS_WIDE, lower)) {
+        for (const name2 of longhands) {
+            result[name2] = lower;
+        }
+        return result;
+    }
+    const match = lexer.matchProperty(name, trimmed);
+    if (!match || !match.matched) {
+        return null;
+    }
+    try {
+        const layers = splitValue(trimmed);
+        if (has(BOX, name)) {
+            return expandBox(longhands, layers, result);
+        }
+        if (has(TWO, name)) {
+            return expandTwo(longhands, layers, result);
+        }
+        if (name === 'background') {
+            return expandBackground(lexer, longhands, layers, result);
+        }
+        if (name === 'font') {
+            return expandFont(lexer, longhands, layers, result);
+        }
+        return expandComponents(lexer, longhands, layers, result);
+    } catch (e) {
+        return null;
+    }
+}
+
+function splitLayers(value) {
+    return splitValue(value).map(layer => layer.join(' ').replace(/ \/ /g, '/'));
+}
+
+function compressFour(values) {
+    if (values[0] === values[1] && values[1] === values[2] && values[2] === values[3]) {
+        return values[0];
+    }
+    if (values[0] === values[2] && values[1] === values[3]) {
+        return values[0] + ' ' + values[1];
+    }
+    if (values[1] === values[3]) {
+        return values[0] + ' ' + values[1] + ' ' + values[2];
+    }
+    return values.join(' ');
+}
+
+function compressBox(name, values) {
+    if (name === 'border-radius') {
+        const hs = [];
+        const vs = [];
+        let vertical = false;
+        for (const value of values) {
+            const parts = value.split(/\s+/);
+            hs.push(parts[0]);
+            if (parts[1] !== undefined && parts[1] !== parts[0]) {
+                vertical = true;
+            }
+            vs.push(parts[1] !== undefined ? parts[1] : parts[0]);
+        }
+        const h = compressFour(hs);
+        return vertical ? h + ' / ' + compressFour(vs) : h;
+    }
+    return compressFour(values);
+}
+
+function compressBackground(names, values) {
+    const layers = names.map((name, idx) => name === 'background-color' ? null : splitLayers(values[idx]));
+    let count = 1;
+    for (const layer of layers) {
+        if (layer && layer.length > count) {
+            count = layer.length;
+        }
+    }
+    const result = [];
+    const colorIndex = names.indexOf('background-color');
+    for (let i = 0; i < count; i++) {
+        const parts = [];
+        for (let j = 0; j < names.length; j++) {
+            if (j === colorIndex) {
+                continue;
+            }
+            const layer = layers[j];
+            parts.push(layer[Math.min(i, layer.length - 1)]);
+        }
+        result.push(parts.slice(0, 1).concat([parts[1] + '/' + parts[2]]).concat(parts.slice(3)).join(' '));
+    }
+    if (colorIndex !== -1) {
+        result[result.length - 1] += ' ' + values[colorIndex];
+    }
+    return result.join(', ');
+}
+
+export function compressShorthand(lexer, propertyName, longhands) {
+    const name = String(propertyName).toLowerCase();
+    const names = LONGHANDS[name];
+    if (!names || !longhands || typeof longhands !== 'object') {
+        return null;
+    }
+    const values = [];
+    for (const longhand of names) {
+        const value = longhands[longhand];
+        if (typeof value !== 'string' || !value.trim()) {
+            return null;
+        }
+        values.push(value.trim());
+    }
+    const wide = values.filter(value => has(CSS_WIDE, value.toLowerCase()));
+    if (wide.length) {
+        if (wide.length === values.length && wide.every(value => value.toLowerCase() === wide[0].toLowerCase())) {
+            return wide[0].toLowerCase();
+        }
+        return null;
+    }
+    if (has(BOX, name)) {
+        return compressBox(name, values);
+    }
+    if (has(TWO, name)) {
+        return values[0] === values[1] ? values[0] : values.join(' ');
+    }
+    if (name === 'background') {
+        return compressBackground(names, values);
+    }
+    if (name === 'font') {
+        return values.slice(0, 4).concat([values[4] + '/' + values[5], values[6]]).join(' ');
+    }
+    return values.join(' ');
+}
